def card(task, wd):
    elf = _build_elf(wd)
    h = _readelf(elf, '-h')
    arch = 'x86-64' if 'X86-64' in h.upper() else '?'
    etype = 'EXEC' if re.search('Type:\\s+EXEC', h) else 'DYN' if 'DYN' in h else '?'
    nsec = len([l for l in _readelf(elf, '-SW').splitlines() if re.match('\\s*\\[\\s*\\d+\\]', l)])
    ov = {'format': 'ELF', 'arch': arch, 'type': etype, 'entry': hex(_entry(elf)), 'sections': nsec}
    out = wd / 'overview.json'
    out.write_text(json.dumps(ov, indent=1))
    return ([check('detected ELF x86-64 executable', arch == 'x86-64' and etype == 'EXEC', [arch, etype], ['x86-64', 'EXEC']), check('section headers counted', nsec > 5, nsec, '>5'), check('negative control: not reported as DYN/shared', etype != 'DYN', etype, 'EXEC')], [out])

def card(task, wd):
    inp = {'target': 'app', 'obligations': [{'id': 'O3', 'claim': 'entrypoint'}, {'id': 'O1', 'claim': 'imports'}, {'id': 'O2', 'claim': 'strings'}]}
    (wd / 'input.json').write_text(json.dumps(inp))

    def build(data):
        obs = sorted(data['obligations'], key=lambda o: o['id'])
        ledger = {'target': data['target'], 'obligations': [{'id': o['id'], 'claim': o['claim'], 'status': 'unmet'} for o in obs]}
        return (ledger, _sha_bytes(_canon(ledger)))
    led1, sha1 = build(inp)
    led2, sha2 = build(json.loads((wd / 'input.json').read_text()))
    other = dict(inp, target='other')
    _, sha_other = build(other)
    out = wd / 'ledger.json'
    out.write_text(json.dumps(led1, indent=1))
    ids = [o['id'] for o in led1['obligations']]
    return ([check('ledger is deterministic across two builds', sha1 == sha2, sha1[:12], sha2[:12]), check('obligations sorted and all three covered', ids == ['O1', 'O2', 'O3'], ids, ['O1', 'O2', 'O3']), check('negative control: a different target yields a different digest', sha1 != sha_other, sha1[:12], sha_other[:12])], [out])

