def card(task, wd):
    old = [{'type': 'App.Svc', 'name': 'Run', 'signature': 'void()'}, {'type': 'App.Svc', 'name': 'Login', 'signature': 'bool(string)'}]
    new = [{'type': 'App.Svc', 'name': 'Run', 'signature': 'void()'}, {'type': 'App.Svc', 'name': 'Login', 'signature': 'bool(string,string)'}]
    (wd / 'old.json').write_text(json.dumps(old))
    (wd / 'new.json').write_text(json.dumps(new))

    def key(m):
        return (m['type'], m['name'], m['signature'])
    strict = set(map(key, old)) & set(map(key, new))
    name_only = {(m['type'], m['name']) for m in old} & {(m['type'], m['name']) for m in new}
    login_changed = ('App.Svc', 'Login') in name_only and ('App.Svc', 'Login', 'bool(string)') not in {key(m) for m in new}
    out = wd / 'managed_compare.json'
    out.write_text(json.dumps({'strict_matches': len(strict), 'name_only_matches': len(name_only)}, indent=1))
    return ([check('Login is not a strict match (signature changed)', login_changed, login_changed, True), check('strict signature matching is stricter than name-only', len(strict) < len(name_only), len(strict), '< %d' % len(name_only)), check('negative control: names alone would wrongly match Login', len(name_only) == 2, len(name_only), 2)], [out])

