def card(task, wd):
    partial = {'obligations': [{'id': 'O1', 'status': 'met'}, {'id': 'O2', 'status': 'met'}, {'id': 'O3', 'status': 'met'}, {'id': 'O4', 'status': 'unmet'}]}
    full = {'obligations': [{'id': o['id'], 'status': 'met'} for o in partial['obligations']]}

    def evaluate(led):
        total = len(led['obligations'])
        met = sum((1 for o in led['obligations'] if o['status'] == 'met'))
        cov = met / total
        return {'coverage': cov, 'ready': cov >= 1.0}
    ep = evaluate(partial)
    ef = evaluate(full)
    out = wd / 'coverage.json'
    out.write_text(json.dumps({'partial': ep, 'full': ef}, indent=1))
    return ([check('partial coverage computed as 0.75', abs(ep['coverage'] - 0.75) < 1e-09, ep['coverage'], 0.75), check('fail-closed: partial coverage is not ready', ep['ready'] is False, ep['ready'], False), check('negative control: full coverage flips ready to True', ef['ready'] is True, ef['ready'], True)], [out])

def card(task, wd):
    MAX = 4096
    good = wd / 'good.json'
    good.write_text(json.dumps({'schema': 'rea/evidence/1', 'target': 'app', 'observations': {}}))
    big = wd / 'big.json'
    big.write_text(json.dumps({'schema': 'rea/evidence/1', 'target': 'x', 'pad': 'A' * 8000}))

    def imp(path):
        if path.stat().st_size > MAX:
            return {'ok': False, 'reason': 'exceeds size bound'}
        data = json.loads(path.read_text())
        if 'schema' not in data:
            return {'ok': False, 'reason': 'no schema'}
        return {'ok': True, 'schema': data['schema']}
    rg = imp(good)
    rb = imp(big)
    out = wd / 'import_result.json'
    out.write_text(json.dumps({'good': rg, 'big': rb}, indent=1))
    return ([check('a small valid bundle is imported', rg['ok'] is True, rg['ok'], True), check('size bound enforced on an oversized bundle', rb['ok'] is False, rb['ok'], False), check('negative control: rejection names the size-bound reason', rb['reason'] == 'exceeds size bound', rb['reason'], 'exceeds size bound')], [out])

