def card(task, wd):
    binary = _cc(wd)
    body = _func_body(_objdump_d(binary), 'main')
    call_lines = [ln for ln in body if re.search('\\bcall\\b', ln)]
    lea_lines = [ln for ln in body if re.search('\\blea\\b', ln)]
    targets = []
