            targets.append(m.group(1))
    out = _jw(wd / 'call_sites.json', {'function': 'main', 'call_sites': targets, 'lea_count': len(lea_lines)})
    return ([check('the call site in main resolves to callee <helper>', 'helper' in targets, targets, 'helper in list'), check('negative control: a data-load (lea) line carries no resolved call target', all(('call' not in ln for ln in lea_lines)) and bool(lea_lines), len(lea_lines), '>0 lea, 0 call')], [out])

